#!/usr/bin/env bash
# Concatenates the pending migrations into one file for the Supabase SQL Editor.
# Regenerate after editing any migration: ./supabase/build-combined.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
mkdir -p supabase/dist
OUT=supabase/dist/apply-all.sql
{
  cat <<'HDR'
-- ═══════════════════════════════════════════════════════════════════
-- Lia — all pending migrations, in order, as one script.
--
-- GENERATED by supabase/build-combined.sh. Do not edit by hand; edit the
-- individual migrations and regenerate.
--
-- Paste the whole thing into the Supabase SQL Editor and run it once, on a
-- database that has none of these migrations. Each migration is idempotent
-- on its own, but the bundle as a whole is NOT safe to re-run over a database
-- that already has the later ones: an early migration cannot re-create a
-- function over the shape a later one gave it, and the paste stops there.
--
-- Applies every migration from 03 up, in order — the files are listed in
-- the section headers below, and supabase/MIGRATIONS.md says what each does.
--
-- This is for a database that has NONE of them. A live database that is
-- part-way up wants only what it lacks: use that migration's own rehearsal
-- (e.g. supabase/test/run-apply-33.sh), which writes a bundle of just that.
--
-- 10_consolidate_account.sql is deliberately NOT included. It is optional, it
-- only suits a single-company deployment, and it needs a user id — see
-- docs/APPLY-MIGRATIONS.md.
--
-- Read the NOTICEs afterwards. 04 reports any inspection whose account it could
-- not work out; those rows stay invisible to the app until assigned.
-- ═══════════════════════════════════════════════════════════════════
HDR
  # 10_consolidate_account.sql is skipped on purpose (see the header); every
  # other migration from 03 on is included. Globbed over every number and
  # filtered, rather than listed by decade: a list by decade silently dropped
  # everything past the last decade somebody remembered to add (10+, then 30+).
  for f in supabase/migrations/[0-9][0-9]_*.sql; do
    case "$(basename "$f")" in 01_*|02_*|10_*) continue ;; esac
    printf '\n-- ┌───────────────────────────────────────────────────────────────────\n'
    printf -- '-- │ %s\n' "$(basename "$f")"
    printf -- '-- └───────────────────────────────────────────────────────────────────\n\n'
    cat "$f"
  done
} > "$OUT"
echo "wrote $OUT ($(wc -l < "$OUT" | tr -d ' ') lines)"
